fn picture_beats(spec:&Value,doc:&Value)->Vec<Value>{let clamp=|b:&mut Value|{b["at"]=json!(num(doc,"start")+(num(b,"at")-num(doc,"start")).min(num(doc,"end")-num(doc,"start")-0.4).max(0.12));};let mut beats=spec["beats"].as_array().cloned().unwrap_or_default();for b in &mut beats{clamp(b)}let callouts:Vec<Value>=doc["callouts"].as_array().into_iter().flatten().filter(|c|c["on"].as_u64().is_some()&&c["at"].as_f64().is_some()).map(|c|{let mut b=json!({"at":c["at"],"items":[c["on"]],"links":[],"co":1});clamp(&mut b);b}).collect();beats.retain(|b|!callouts.iter().any(|c|(num(c,"at")-num(b,"at")).abs()<0.9&&!b["items"].as_array().is_some_and(|items|items.contains(&c["items"][0]))));for c in callouts{if !beats.iter().any(|b|(num(b,"at")-num(&c,"at")).abs()<0.35&&b["items"].as_array().is_some_and(|items|items.contains(&c["items"][0]))){beats.push(c)}}beats.sort_by(|a,b|num(a,"at").total_cmp(&num(b,"at")));let mut out=Vec::new();for b in beats{if b["co"]==1||out.last().is_none_or(|p|num(&b,"at")-num(p,"at")>=0.45){out.push(b)}}out}
fn array<'a>(v:&'a Value,key:&str)->Result<&'a Vec<Value>,String>{v[key].as_array().ok_or_else(||format!("{key} must be an array"))}
fn swap(s:&'static str)->&'static str{match s{"l"=>"t","r"=>"b","t"=>"l",_=>"r"}}
fn picture_geometry(name:&str,n:usize,out:bool,upright:bool)->Result<(Vec<(f64,f64,f64)>,Option<Frame>,Vec<(usize,usize,&'static str,&'static str)>),String>{let(mut tiles,mut frame,mut edges)=match(name,n){("single",1)=>(vec![(320.0,200.0,180.0)],None,vec![]),("row",2)=>(vec![(180.0,200.0,150.0),(460.0,200.0,150.0)],None,vec![(0,1,"r","l")]),("row",3)=>(vec![(80.0,200.0,116.0),(320.0,200.0,116.0),(560.0,200.0,116.0)],None,vec![(0,1,"r","l"),(1,2,"r","l")]),("hub",3..=5)=>{let points=match n{3=>vec![(85.0,200.0),(555.0,200.0)],4=>vec![(85.0,200.0),(555.0,92.0),(555.0,308.0)],_=>vec![(85.0,92.0),(85.0,308.0),(555.0,92.0),(555.0,308.0)]};let mut tiles=vec![(320.0,200.0,140.0)];let mut edges=Vec::new();for(i,(x,y))in points.into_iter().enumerate(){tiles.push((x,y,104.0));edges.push((0,i+1,if x>320.0{"r"}else{"l"},if x>320.0{"l"}else{"r"}));}(tiles,None,edges)},("tree",3..=4)=>{let kids=if n==3{vec![190.0,450.0]}else{vec![100.0,320.0,540.0]};let mut tiles=vec![(320.0,70.0,116.0)];let mut edges=Vec::new();for(i,x)in kids.into_iter().enumerate(){tiles.push((x,320.0,108.0));edges.push((0,i+1,"b","t"));}(tiles,None,edges)},("cycle",3)=>(vec![(320.0,70.0,116.0),(520.0,320.0,116.0),(120.0,320.0,116.0)],None,vec![(0,1,"r","t"),(1,2,"l","r"),(2,0,"t","l")]),("boundary",1..=2)=>{let mut tiles=if n==1{vec![(180.0,200.0,140.0)]}else{vec![(100.0,200.0,112.0),(260.0,200.0,112.0)]};if out{tiles.push((570.0,200.0,116.0));}(tiles,Some((16.0,84.0,328.0,232.0)),if out{vec![(n,usize::MAX,"l","r")]}else{vec![]})},_=>return Err(format!("unsupported picture layout/count {name}/{n}"))};if upright{for t in &mut tiles{std::mem::swap(&mut t.0,&mut t.1)}frame=frame.map(|(x,y,w,h)|(y,x,h,w));for e in &mut edges{e.2=swap(e.2);e.3=swap(e.3);}}Ok((tiles,frame,edges))}
fn picture_size(spec:&Value,w:f64,h:f64)->(f64,bool){let up=h>w*0.9&&matches!(label(spec,"layout"),"single"|"row"|"hub"|"boundary");(w.min(h*if up{400.0/640.0}else{640.0/400.0}),up)}
