 for(le,(a,b,sa,sb))in edges.into_iter().enumerate(){let mut runs:Vec<(&str,usize,usize)>=Vec::new();for(q,state)in states.iter().enumerate(){let links=&state["links"];let kind=links.as_str().or_else(||links.get(le).and_then(Value::as_str)).unwrap_or("none");if !matches!(kind,"none"|"arrow"|"back"|"line"|"dashed"|"blocked"){return Err(format!("unknown picture link {kind}"))}if kind!="none"&&(all[q][a].is_null()||(b!=usize::MAX&&all[q][b].is_null())){return Err("picture link has empty endpoint".into())}if let Some(last)=runs.last_mut(){if last.0==kind{last.2=q+1;continue}}runs.push((kind,q,q+1));}for(kind,from,to)in runs{if kind=="none"{continue}let ia=ids[a].ok_or("picture source is empty")?;let ib=if b==usize::MAX{frame_id.ok_or("picture boundary has no frame")?}else{ids[b].ok_or("picture target is empty")?};self.edge(if kind=="back"{ib}else{ia},if kind=="back"{ia}else{ib},match kind{"arrow"|"back"=>"flow","line"=>"structure","dashed"=>"affinity",_=>"blocked"},Some(if kind=="back"{(sb,sa)}else{(sa,sb)}));self.edges.last_mut().unwrap().extra=json!({"fixA":if from>0{json!(rel(num(&states[from],"at"))+0.25)}else{Value::Null},"gone":if to<states.len(){state_at(to)}else{Value::Null},"flashes":beats.iter().filter(|b|b["links"].as_array().is_some_and(|v|v.contains(&json!(le)))).map(|b|rel(num(b,"at"))).collect::<Vec<_>>()});}}
