 fn illustration(&mut self,v:&Value,variant:&str)->Result<(),String>{let bw=self.s.w-2.0*self.s.margin;let mx=self.s.margin;let cx=self.s.w/2.0;let cy=(self.s.top+self.s.bottom)/2.0;let spec=&v["picture"];if matches!(variant,"picture"|"bare"){self.heading(v);let top=if !label(v,"title").is_empty(){self.s.top-8.0}else if self.s.tall{self.s.top-60.0}else{84.0};let bh=self.s.bottom-top;let(pw,up)=picture_size(spec,bw,bh);let pw=pw*if v.get("callouts").is_some(){0.8}else{1.0};let ph=pw*if up{640.0/400.0}else{400.0/640.0};return self.picture(v,cx-pw/2.0,top+(bh-ph)/2.0,pw,up)}if !matches!(variant,"stage"|"panel"){return Err(format!("unknown illustration variant {variant}"))}let content=text(v,"text")?;let(width,max,min,lines)=if variant=="stage"{(bw-88.0,46.0,30.0,2)}else if self.s.tall{(bw-24.0,44.0,28.0,5)}else{(440.0,50.0,30.0,6)};let(fs,lines)=crate::typography::fit_block(content,&self.s.theme,max,min,lines,width);let lh=(fs*1.2).round();let h=lines as f64*lh+8.0;if variant=="panel"&&!self.s.tall{let title=label(v,"title").to_uppercase();let eb=if title.is_empty(){0.0}else{crate::typography::fit_one_line(&title,&self.s.theme,24.0,18.0,440.0)};let y=cy-(h+if eb>0.0{eb*1.4+22.0}else{0.0})/2.0;if eb>0.0{self.text("eyebrow",&title,(744.0,y,440.0,(eb*1.4).round()),"focus",eb,(eb*1.3).round(),"left",json!({}));}self.text("statement",content,(744.0,y+if eb>0.0{eb*1.4+22.0}else{0.0},440.0,h),"focus",fs,lh,"left",json!({"hl":highlight(v)}));self.picture(v,64.0,cy-200.0,cx,false)?;}else{let py=if variant=="panel"{self.s.top-20.0}else if self.s.tall{self.s.top-60.0}else{76.0};let maxh=self.s.bottom-h-if variant=="panel"{24.0}else{32.0}-py;let(pw,up)=picture_size(spec,if variant=="panel"{bw}else{bw-48.0},maxh);self.picture(v,cx-pw/2.0,py,pw,up)?;self.text("statement",content,(mx+if variant=="panel"{12.0}else{44.0},self.s.bottom-h,width,h),if variant=="stage"{"item"}else{"focus"},fs,lh,"center",json!({"hl":highlight(v)}));}Ok(())}
